package org.sleepwell.app;

import android.app.Activity;
import android.content.Context;
import android.os.Bundle;
import android.widget.LinearLayout;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Read-only real paired evidence. Never resumes an old connection or replaces the original signal. */
public final class PairMotionSavedActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private int generation;private long selected;private List<JSONObject> links=List.of(),windows=List.of();private RecordEntry record;private String error="";
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);selected=saved==null?getIntent().getLongExtra("record",0):saved.getLong("selected");load();}
    private void load(){int request=++generation;Context app=getApplicationContext();Records.Factory factory=Records.factory;long wanted=selected;LinearLayout body=page();Design.text(body,"Loading saved paired readings…",14,400,Design.MUTED);worker.execute(()->{try(Store store=factory.open(app)){RecordEntry entry=wanted==0?null:Records.get(store,wanted);List<JSONObject> savedLinks=wanted==0?store.rows("SELECT l.*,s.start AS night_start,s.end AS night_end FROM pair_links l JOIN sessions s ON s.id=l.session WHERE s.end IS NOT NULL ORDER BY l.started DESC LIMIT 200"):store.rows("SELECT * FROM pair_links WHERE session=? ORDER BY started",""+wanted);List<JSONObject> data=wanted==0?List.of():store.rows("SELECT w.* FROM pair_windows w JOIN pair_links l ON l.link=w.link WHERE l.session=? ORDER BY w.start",""+wanted);runOnUiThread(()->{if(isDestroyed()||isFinishing()||request!=generation)return;record=entry;links=savedLinks;windows=data;error="";render();});}catch(Exception unavailable){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;error="Saved paired readings are unavailable. The original recording is unchanged.";render();});}});}
    private LinearLayout page(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Paired movement",()->{if(selected!=0&&!getIntent().hasExtra("record")){selected=0;load();}else finish();});Design.space(body,14);return body;}
    private void render(){LinearLayout body=page();if(!error.isEmpty()){Design.text(body,error,15,500,Design.BROWN);Design.button(body,"Try again",true,this::load);return;}if(selected==0){if(links.isEmpty()){Design.text(body,"No paired recordings yet",22,600,Design.INK);Design.space(body,10);Design.text(body,"Pair two active manual Phone movement recordings to save separate movement and alignment evidence.",14,400,Design.MUTED);return;}Set<Long> seen=new HashSet<>();for(JSONObject link:links){long session=link.optLong("session");if(!seen.add(session))continue;String date=java.time.Instant.ofEpochMilli(link.optLong("night_start")).atZone(java.time.ZoneId.systemDefault()).toLocalDate().toString();Design.item(body,"report",date,link.isNull("night_end")?"Current recording":"Saved recording #"+session,()->{selected=session;load();});}return;}if(record==null){Design.text(body,"The recording no longer exists.",15,500,Design.BROWN);return;}if(links.isEmpty()){Design.text(body,"No paired measurements saved for this recording.",15,400,Design.MUTED);return;}long start=record.edit.start,end=record.edit.end;Design.text(body,"Two phones · separate raw movement",21,600,Design.INK);Design.space(body,6);Design.text(body,"5-second averages · missing intervals stay blank. Peer clocks were aligned when possible; these are phone measurements, not sleep stages.",12,400,Design.MUTED);List<JSONObject> visible=Records.window(windows,start,end);String[] labels={"This phone · raw","Other phone · fresh aligned","Experimental shared-motion reduction"},fields={"own","peer","filtered"};for(int i=0;i<fields.length;i++){String field=fields[i];boolean measured=false;for(JSONObject row:visible)if(!row.isNull(field)){measured=true;break;}RecordUi.heading(body,labels[i]);if(measured)body.addView(new RecordChart(this,visible,field,start,end,false,record.zone()).measurement(labels[i]),new LinearLayout.LayoutParams(-1,Design.dp(this,155)));else Design.text(body,i==2?"No filtered values saved. Raw measurements remain above.":"No measurements available in this edited period.",13,400,Design.MUTED);}Map<String,Long> quality=new LinkedHashMap<>();for(JSONObject row:visible){long from=Math.max(start,row.optLong("start")),to=Math.min(end,row.optLong("time"));if(to>from)quality.merge(row.optString("quality"),to-from,Long::sum);}RecordUi.heading(body,"Paired interval quality");for(Map.Entry<String,Long> state:quality.entrySet())PlanActivity.detail(body,"clock",quality(state.getKey()),null,RecordUi.duration(state.getValue()),null);for(JSONObject link:links)if(link.isNull("ended"))Design.text(body,"This link has no confirmed close receipt. An interrupted connection cannot be resumed automatically.",12,500,Design.BROWN);Design.space(body,8);Design.text(body,"Each graph uses its own relative scale. Filtering is an optional engineering heuristic, not a reliable separation of people. Original phone epochs remain unchanged.",12,400,Design.MUTED);}
    private static String quality(String value){return switch(value){case "COMMON_REDUCED"->"Shared-motion reduction";case "FRESH_RAW"->"Fresh paired raw";case "WAITING_SYNC"->"Clock not aligned";case "PEER_MISSING"->"Peer missing / low overlap";case "LOW_COVERAGE"->"Own signal missing";case "TIMING_LOST"->"Timing gap";default->"Raw phone only";};}
    @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putLong("selected",selected);}@Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
